comments.body:
nit: `std::vector` offers more idiomatic methods here, while you're touching this:


<details>
<summary>git diff on f3a095ad3c</summary>

```diff
diff --git a/src/chain.h b/src/chain.h
index a4f96c4ce8..88ccb0f545 100644
--- a/src/chain.h
+++ b/src/chain.h
@@ -394,13 +394,13 @@ public:
     /** Returns the index entry for the genesis block of this chain, or nullptr if none. */
     CBlockIndex* Genesis() const
     {
-        return m_chain.size() > 0 ? &(m_chain[0].get()) : nullptr;
+        return m_chain.empty() ? nullptr : &m_chain.front().get();
     }

     /** Returns the index entry for the tip of this chain, or nullptr if none. */
     CBlockIndex* Tip() const
     {
-        return m_chain.size() > 0 ? &(m_chain[m_chain.size() - 1].get()) : nullptr;
+        return m_chain.empty() ? nullptr : &m_chain.back().get();
     }

     /** Returns the index entry at a particular height in this chain, or nullptr if no such height exists. */

```
</details>

